INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(261, 'koKR', 'Szkarłatną ścieżką', 'Powiem wprost. Jesteśmy w stanie wojny z Plagą. To zło, które deprawuje nasz lud i zaraża naszą ziemię. Trzeba je powstrzymać, zanim nas przytłoczy i pogrąży nasz świat w mroku. My, członkowie Szkarłatnej Krucjaty, przysięgliśmy walczyć z Plagą ciałem i duszą.$B$BJeśli jesteś z nami, zbierz się na odwagę i dowiedź swojej lojalności – zniszcz nieumarłych pustoszycieli Mrocznego Pustkowia w Dolinie Kości na południu.$B$BZrób to, a Krucjata przyjmie cię w swoje objęcia.', 'Zniszcz 30 nieumarłych pustoszycieli, a następnie wróć do brata Antona w Punkcie Nijela.', '', 'Wróć do brata Antona w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1277, 'koKR', '<nyi> <TXT> Ślady kopyt centaurów', 'Kagoro wyjawił, że ślady kopyt centaurów należą do jakichś frajerów z Maraudonu.', 'Spuść im łomot.', '', '', '', '', '', '', 0),
(1365, 'koKR', 'Chan Dez\'hepah', 'Kolkarowie nie są jedynymi centaurami Mrocznego Pustkowia. Po tych suchych równinach wędruje wiele klanów, które walczą ze sobą i giną. I dobrze, że biją się między sobą, bo są silne i brutalne. Gdyby centaury zjednoczyły się przeciwko nam, byłyby groźnym wrogiem.$B$BMusimy się z nimi rozprawić, zanim się zjednoczą.$B$BTwoim pierwszym zadaniem jest wprowadzić zamęt w klanie Kolkarów. Zrób to, zabijając ich przywódcę, chana Dez\'hepaha.$B$BWioska Kolkarów leży na północny wschód stąd. Idź i niech los ci sprzyja.', 'Przynieś głowę chana Dez\'hepaha Felgurowi Dwa Cięcia w Mrocznym Pustkowiu.', '', 'Wróć do Felgura Dwa Cięcia na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1366, 'koKR', 'Nagroda za centaury', 'Skoro klany centaurów już się ciebie boją, czas je wykrwawić. Wędrując po Mrocznym Pustkowiu, poluj na centaury. Nie obchodzi mnie, z którego klanu. Po prostu zbieraj uszy. Całą stertę uszu.$B$BPrzerzedzając ich szeregi, osłabisz ich determinację i wybijesz im z głów wszelkie myśli o ekspansji.$B$BUdanych łowów, $N.', 'Przynieś 15 uszu centaurów Felgurowi Dwa Cięcia w Mrocznym Pustkowiu.', '', 'Wróć do Felgura Dwa Cięcia na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1367, 'koKR', 'Przymierze z Magram', 'Aby pokonać centaury, musimy obrócić ich nienawiść przeciwko nim samym. Sprzymierzymy się z jednym z klanów i dzięki niemu dowiemy się, jak pokonać wszystkie klany.$B$BJeśli postanowisz sprzymierzyć się z Magram, zabijaj ich wrogów, Gelkis. Tak zdobędziesz szacunek Magram. Gdy zdobędziesz go dość, spotkaj się z rzecznikiem Magram, Warugiem, na obrzeżach Wioski Magram, w południowo-wschodniej części Mrocznego Pustkowia.', 'Zdobądź u Magram reputację na poziomie Przyjazny, a następnie porozmawiaj z Warugiem.', '', 'Porozmawiaj z Warugiem w Wiosce Magram w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1368, 'koKR', 'Przymierze z Gelkis', 'Aby pokonać centaury, musimy obrócić ich nienawiść przeciwko nim samym. Sprzymierzymy się z jednym z klanów i dzięki niemu dowiemy się, jak pokonać wszystkie klany.$B$BJeśli postanowisz sprzymierzyć się z Gelkis, zabijaj ich najbardziej znienawidzonych rywali, Magram. Gdy zdobędziesz szacunek Gelkis, spotkaj się z szamanką Gelkis, Uthek Mądrą, na obrzeżach Wioski Gelkis, w południowo-zachodniej części Mrocznego Pustkowia.', 'Zdobądź u Gelkis reputację na poziomie Przyjazny, a następnie porozmawiaj z Uthek Mądrą.', '', 'Porozmawiaj z Uthek Mądrą w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1369, 'koKR', 'Rozbite łzy', 'Gelkis myślą, że nasza matka centaurów, Theradras, nas chroni. Są głupi. Nikt nie chroni centaurów. Magram nie potrzebują ochrony! Jesteśmy najsilniejsi!$B$BPokaż Gelkis, że są głupi. Idź do jaskini w ich wiosce. Gromadzą w tej jaskini kryształy, łzy Theradras. Zniszcz łzy i przynieś mi rozbite kawałki!', 'Utrzymaj swoją reputację u Magram i przynieś 3 rozbite łzy Warugowi w Wiosce Magram.', '', 'Wróć do Waruga w Wiosce Magram w Mrocznym Pustkowiu.', 'Zniszczone łzy', '', '', '', 0),
(1370, 'koKR', 'Kradzież zapasów', 'Gdy nie walczymy, polujemy na mięso. Mięso daje nam siłę, a pełne brzuchy walczą mocniej niż puste.$B$BZ Magram jest tak samo. Trzymają zapas mięsa, żeby dłużej walczyć między łowami. Jeśli napadniesz na ich wioskę na wschodzie i zabierzesz ich zapasy mięsa, ich siła upadnie.', 'Przynieś 6 worków prymitywnie suszonego mięsa Uthek Mądrej w Wiosce Gelkis.', '', 'Wróć do Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1371, 'koKR', 'Gadżet dla Waruga', 'Dawno temu do Mrocznego Pustkowia przybył mały gnom. Miał konie i wóz, a na wozie dziwne rzeczy. Śmieszne rzeczy. Rzeczy, które paliły się różnymi kolorami. Rzeczy, które się ruszały, a nie były żywe. Zabiłem małego gnoma, ale przedtem... rozśmieszył mnie.$B$BZatrzymałem z jego wozu rzecz, którą lubiłem najbardziej. To był człowiek z drewna i machał do mnie, aż go uderzyłem i zepsułem.$B$BChcę nowego. Zdobądź mi nowego!', 'Utrzymaj swoją reputację u Magram i przynieś zaawansowaną kukłę treningową Warugowi w Wiosce Magram w Mrocznym Pustkowiu.', '', 'Wróć do Waruga w Wiosce Magram w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1373, 'koKR', 'Ongeku', 'Musisz dowieść jeszcze więcej, a twoje następne zadanie zaprowadzi cię daleko, więc na razie Gelkis będą walczyć z Magram bez ciebie.$B$BZiemia szepcze wiele sekretów tym, którzy słuchają. Jeden sekret, który słyszę, mówi o czerwonym krysztale. Nazywa się draenetyst i jest nowy w naszej ziemi. Pochodzi z miejsca, gdzie góry latają, a rządzą demony.$B$BPrzynieś mi odłamek draenetystu, a wzmocni on moją magię! Odłamek jest w miejscu zwanym Moczarami Smutków, a trzyma go zagubiony Ongeku.', 'Utrzymaj swoją reputację u Gelkis i przynieś odłamek draenetystu Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', 'Wróć do Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1374, 'koKR', 'Chan Jehn', 'Ziemia do mnie mówi, a mówi, że Magram słabną. Teraz czas zabić ich chana!$B$BPrzynieś mi głowę chana Magram, Jehna!', 'Przynieś głowę chana Jehna Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', 'Wróć do Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1375, 'koKR', 'Chan Shaka', 'Pomagasz Magram i lubię cię. Teraz zabij chana Gelkis! To chan Shaka, a ja chcę jego głowy! Chcę patrzeć na jego głowę i śmiać się z niego!', 'Utrzymaj swoją reputację u Magram i przynieś głowę chana Shaki Warugowi w Wiosce Magram w Mrocznym Pustkowiu.', '', 'Wróć do Waruga w Wiosce Magram w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1380, 'koKR', 'Chan Hratha', '$N, $gpomogłeś:pomogłaś; nam przeciw Magram. Teraz pomóż nam pokonać Maraudine! Zabij głowę ich klanu, chana Hrathę!$B$BAby stanąć z nim twarzą w twarz, zadmij w róg wojenny Maraudine. Stoi na wysokim urwisku w Dolinie Włóczni.$B$BAle żeby zadąć w róg, musisz zdobyć ustnik rogu wojennego. Są rzadkie, noszą je tylko zaufane centaury Maraudine.$B$BGdy róg zabrzmi, przyjdą centaury. Zabijaj je, aż pojawi się Hratha.$B$BChan Hratha ma kawałek... klucza. Przynieś mi go...', 'Utrzymaj swoją reputację u Gelkis i przynieś fragment klucza Maraudine Uthek Mądrej w Wiosce Gelkis.', '', 'Wróć do Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1381, 'koKR', 'Chan Hratha', 'Chan Gelkis nie żyje, a teraz upadną Maraudine! Zabij chana Maraudine, Hrathę!$B$BAby stanąć z nim twarzą w twarz, zadmij w róg na wysokim urwisku w Dolinie Włóczni. Ale żeby zadąć w róg, potrzebujesz ustnika. Żeby zdobyć ustnik, zabijaj centaury Maraudine. Zabijaj, aż znajdziesz ustnik. Wtedy zadmij w róg.$B$BZrób to, a centaury Maraudine przyjdą do wieży. Zabijaj je, aż pojawi się chan Hratha. Hratha ma kawałek klucza. Daj ten kawałek mnie...', 'Utrzymaj swoją reputację u Magram i przynieś fragment klucza Maraudine Warugowi w Wiosce Magram w Mrocznym Pustkowiu.', '', 'Wróć do Waruga w Wiosce Magram w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1382, 'koKR', 'Dziwne przymierze', 'Mamy szczęście, że klany centaurów walczą między sobą, bo gdyby połączyły się w jedną siłę, byłyby nie do powstrzymania. Tak, mamy szczęście i powinniśmy to wykorzystać.$B$BJeden z klanów centaurów, klan Gelkis, toczy brutalną wojnę z klanem Magram. Jeśli zaatakujemy Magram, być może zdołamy zawrzeć przymierze z Gelkis.$B$BPorozmawiaj z Uthek Mądrą na obrzeżach obozów Gelkis w południowo-zachodniej części Mrocznego Pustkowia. Za jej pośrednictwem moglibyśmy zawrzeć przymierze z Gelkis.', 'Zdobądź u Gelkis reputację na poziomie Przyjazny, a następnie porozmawiaj z Uthek Mądrą.', '', 'Wróć do Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1384, 'koKR', 'Napad na Kolkarów', 'Kolkarowie myślą, że ich magia jest silna. Oni nie znają magii! Nie poznaliby magii, nawet gdyby ich ugryzła!$B$BPokażesz im, że ich magia jest słaba. Idź do Kolkarów na północnym wschodzie i zabijaj ich. Zabierz ich talizmany. Przynieś mi talizmany, a wrzucę je w ogień i będę się śmiać!', 'Utrzymaj swoją reputację u Gelkis i przynieś 10 prymitywnych talizmanów Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', 'Wróć do Uthek Mądrej w Wiosce Gelkis w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1385, 'koKR', 'Brutalna polityka', 'Mroczne Pustkowie to kraina ogarnięta wojną. Centaury walczą między sobą, a my sądzimy, że zwycięzca wyleje się poza swoje ziemie i zagrozi naszym twierdzom. Na to nie możemy pozwolić.$B$BMusimy się dowiedzieć, jak pokonać centaury, a żeby to zrobić... musimy sprzymierzyć się z jednym z klanów. Centaury Magram toczą wojnę z Gelkis. Jeśli będziesz walczyć z Gelkis, Magram być może rozważą przymierze.$B$BZdobądź przychylność Magram, a potem porozmawiaj z Warugiem w Wiosce Magram w południowo-wschodniej części Mrocznego Pustkowia.', 'Zdobądź u Magram reputację na poziomie Przyjazny, a następnie porozmawiaj z Warugiem.', '', 'Porozmawiaj z Warugiem w Wiosce Magram w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1386, 'koKR', 'Szturm na Kolkarów', 'Kolkarowie myślą, że są silni, ale my się z nich śmiejemy! Śmiejemy się i zabijamy ich! Ty też ich zabijaj. Pokaż mi, że umiesz zabijać Kolkarów tak jak my. Idź na północ i zabij ich wszystkich!', 'Utrzymaj swoją reputację u Magram. Zabij 12 centaurów Kolkarów, 12 Kolkarów zwiadowców i 6 Kolkarów mocarzy, a następnie wróć do Waruga w Wiosce Magram w Mrocznym Pustkowiu.', '', 'Wróć do Waruga w Wiosce Magram w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1387, 'koKR', 'Nagroda za centaury', 'Rasa centaurów składa się z wielu klanów. Każdy ma własnego przywódcę i własne cele, ale wszystkie klany łączy jedno. Okrucieństwo.$B$BJeśli mamy kiedykolwiek zaznać pokoju, centaury muszą zniknąć. Dlatego zlecam ci właśnie to zadanie.$B$BWędrując po Mrocznym Pustkowiu, poluj na centaury i obcinaj im uszy. Przynieś mi wiele, wiele uszu.$B$BZrób to w służbie Przymierza, $N, a będziemy o krok bliżej końca wojny.', 'Przynieś 15 uszu centaurów kapralowi Melkinsowi w Punkcie Nijela w Mrocznym Pustkowiu.', '', 'Wróć do kaprala Melkinsa w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1437, 'koKR', 'Poszukiwania Vahlarriela', 'Jestem Vahlarriel, $N. Przybyłem tu, by odnaleźć dwoje zaginionych członków darnasyjskiego rodu kupieckiego – rodu Malemów. Głowa rodu obawia się najgorszego, a ja mam zrobić wszystko, co w mojej mocy, by odnaleźć jego zaginione dzieci. Nie zacząłem jeszcze szukać Tyranisa ani Dalindy, ale mam nadzieję, że nie zabawię tu długo.$B$BOstatnie wieści mówią, że kilka tygodni temu przejeżdżali przez Góry Szponogłazy.$B$BJeśli znajdziesz ich wóz, proszę, natychmiast mnie odszukaj.', 'Odnajdź i przeszukaj wóz Tyranisa i Dalindy Malemów w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1438, 'koKR', 'Poszukiwania Vahlarriela', 'Odszukaj Dalindę i Tyranisa, jeśli zdołasz, i wróć do mnie z tym, co ustalisz. Poszukiwania zacznij w tej fortecy. Ja natychmiast skontaktuję się z przełożonymi w Darnassus i powiadomię ich o sytuacji.$B$B$N, jest jeszcze coś, co chcę ci wyraźnie uświadomić. Moi przełożeni są nieco zaniepokojeni Tyranisem i powodami, dla których tu przybył. Bardziej zależy im na tym, by odnaleźć Dalindę i sprowadzić ją bezpiecznie do domu. Tyranisa trzeba... ocenić, zanim zostanie zabrany do domu.', 'Odszukaj Dalindę Malem w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1439, 'koKR', 'W poszukiwaniu Tyranisa', 'Przyprowadzono nas tu po tym, jak orkowie wyrżnęli wszystkich naszych strażników i służących. Och, jakie potworności im wyrządzili! Byłam pewna, że zabiją nas od razu na miejscu, ale okazało się, że mają inne plany.$B$BTyranis próbował z nimi rozmawiać. Chyba chciał im zaimponować swoją wiedzą o tajemnej mocy... Nie wiem dlaczego.$B$BProszę, nie mogę stąd odejść, dopóki nie dowiem się, co stało się z moim bratem. Odszukaj go, a gdy jego los będzie znany, wróć po mnie.', 'Odszukaj Tyranisa Malema w Mrocznym Pustkowiu.', '', 'Wróć do Dalindy Malem w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1440, 'koKR', 'Powrót do Vahlarriela', 'A więc to już pora? Doceniam twoje starania, a gdyby później nie było ku temu okazji, pozwól, że już teraz podziękuję ci za wszystko, co $gzrobiłeś:zrobiłaś; dla mnie i mojej rodziny. Jeśli jesteś $ggotów:gotowa;, nic mnie tu już nie trzyma – możemy ruszać, gdy uznasz, że nadszedł właściwy moment.', 'Wyprowadź Dalindę Malem z Fortecy Gromowego Topora, a następnie wróć do Vahlarriela Demonobójcy w Mrocznym Pustkowiu.', 'Uratuj Dalindę Malem', 'Wróć do Vahlarriela Demonobójcy w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1454, 'koKR', 'Wrak statku Karnitola', 'Moje pierwsze zlecenie jest dla maga Karnitola – jakiegoś tam szlachcica z Wichrogrodu. Podobno jego statek zaatakowały morskie olbrzymy u wybrzeży północno-zachodniego Mrocznego Pustkowia. On i jego słudzy próbowali wynieść na brzeg jedną z jego cenniejszych skrzyń, ale kiedy morskie olbrzymy zaatakowały całymi gromadami, porzucił ją i teleportował siebie i sługi w bezpieczne miejsce.$B$BChce, żebyśmy odnaleźli skrzynię i jej zawartość i zwrócili mu je w Wichrogrodzie.', 'Odnajdź skrzynię Karnitola w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1455, 'koKR', 'Wrak statku Karnitola', 'Przez chwilę zastanawiasz się, czym wyważono skrzynię, i dostrzegasz na jej bokach i wieku długie, głębokie zadrapania, które świadczą, że zainteresował się nią ktoś inny niż człowiek czy olbrzym. Ślady nie wyglądają na zrobione sztyletem ani mieczem.$B$BPo przeszukaniu skrzyni stwierdzasz, że jest zupełnie pusta.$B$BNie mając innego wyjścia, zamykasz skrzynię i szykujesz się do drogi. Kreldig będzie rozczarowany.', 'Wróć do Kreldiga Ungora w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1456, 'koKR', 'Wrak statku Karnitola', 'Intrygujące.$B$BCóż, może jeszcze nie wszystko stracone.$B$BNa tym samym wybrzeżu, ale dalej na północ, przy Wyspie Ranazjar, na dnie oceanu leżą ruiny nocnych elfów. Mieszka tam plemię nag, Wężowe Ostrze. Myślę, że to nasz najlepszy trop.$B$BJeśli oddział zwiadowczy zapuścił się tak daleko na południe, to musiał być całkiem potężny. Jeśli chcesz odnaleźć rzeczy Karnitola, zacząłbym od potężniejszych nag: łowców fal albo morskich wiedźm.', 'Odnajdź torbę Karnitola i zanieś ją Kreldigowi Ungorowi w Mrocznym Pustkowiu.', '', 'Wróć do Kreldiga Ungora w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1458, 'koKR', 'Składniki dla Odzyskiwaczy sp. z o.o.', 'Jedno z moich zadań tutaj to odebranie składników dla Leftwitcha, gnomiego maga z Kharanos. Roetten uważa, że to łatwy grosz, skoro i tak tu jesteśmy. Nie bardzo go obchodzi, że i bez tego brakuje nam rąk do pracy.$B$BPierwsze pozycje z jego listy powinny być dość łatwe do zdobycia, a każdy, kto mi pomoże, nieźle na tym zarobi.$B$BPotrzebuję trochę rogów i pazurów satyrów Nienawistnej Furii, którzy siedzą na wschód stąd. Przynieś mi je, a zabierzemy się za resztę listy.', 'Przynieś 10 pazurów Nienawistnej Furii i 10 rogów Nienawistnej Furii Kreldigowi Ungorowi w Mrocznym Pustkowiu.', '', 'Wróć do Kreldiga Ungora w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1459, 'koKR', 'Składniki dla Odzyskiwaczy sp. z o.o.', 'Następne na liście Leftwitcha jest... zaraz... hmm. O, jest.$B$BDość proste, ale wskazówki ma bardzo dokładne. Potrzebuje jadu skorpaszy i skóry kodo. Drobnym drukiem dopisał, że jedno i drugie ma pochodzić z konkretnych stworzeń: jad z któregokolwiek skorpasza, a skóra ze starego kodo, nie z umierających ani prastarych.$B$BMagowie, mówię ci, czego to oni nie chcą... dziwactwo i tyle.', 'Przynieś 7 fiolek jadu skorpasza i 3 skóry starego kodo Kreldigowi Ungorowi w Mrocznym Pustkowiu.', '', 'Wróć do Kreldiga Ungora w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1465, 'koKR', 'Poszukiwania Vahlarriela', 'Przeszukując dalej wóz, znajdujesz nie tylko wisior, ale też ślady stóp prowadzące na południe. W oddali widzisz dym unoszący się nad dużym fortem. To dym z podtrzymywanego ogniska, a nie z płonących budynków, a instynkt podpowiada ci, że Malemowie, jeśli jeszcze żyją, zostali zabrani w tamtą stronę.$B$BUważasz, że Vahlarriel w Punkcie Nijela powinien nie tylko zobaczyć znaleziony wisior, ale też dowiedzieć się o śladach życia na południu.', 'Zanieś wisior Malemów Vahlarrielowi Demonobójcy w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1466, 'koKR', 'Składniki dla Odzyskiwaczy sp. z o.o.', 'To ostatnia pozycja i nie będę kłamał, nie jest przyjemna. Spodziewam się też, że zajmie ci trochę więcej czasu niż pozostałe.$B$BDość ostrzeżeń, bierzmy się do roboty. Leftwitch pisze, że potrzebuje: dziesięciu mózgów pożeraczy many, łowców magów albo łowców linii mocy. Dziesięciu skrzydeł Otchłani od panny Otchłani, siostry Otchłani albo czarodziejki Otchłani. I... dziesięciu fiolek krwi stróża zagłady od kapitana albo lorda stróżów zagłady.$B$BProste, co? Rany... jeśli chcesz sobie to odpuścić, zrozumiem.', 'Przynieś 10 mózgów ogarów spaczenia, 10 skrzydeł Otchłani i 10 fiolek krwi stróża zagłady Kreldigowi Ungorowi w Mrocznym Pustkowiu.', '', 'Wróć do Kreldiga Ungora w Punkcie Nijela w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1480, 'koKR', 'Plugawiciel', 'Zdarta skóra cuchnie zgnilizną i jest zaskakująco giętka jak na coś, co wygląda na suche i kruche.$B$BGdy ją rozwijasz, wyraźnie widzisz po jednej stronie czerwone znaki jakiegoś języka. U dołu skóry widnieje bardzo wyraźny symbol – domyślasz się, że to coś w rodzaju podpisu.$B$BMoże Maurin umiałby powiedzieć ci o tym coś więcej?', 'Zanieś zdartą skórę demona Maurinowi Kościołupowi w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1481, 'koKR', 'Plugawiciel', 'Sądzę, że zdołam odnaleźć tego demonicznego lorda, jeśli dostanę właściwe składniki.$B$BJeśli rzeczywiście jest tak potężny, jak podejrzewam, będę potrzebował przedmiotów zdobytych na śmiertelnie groźnych stworzeniach. Ale działasz w imieniu wodza, więc jestem pewien, że przyjmiesz moje zadanie.$B$BNajpierw będę musiał przełamać wszelkie osłony, jakimi chroni się przed wieszczeniem. Do tego potrzebuję skalpu satyra – ale nie byle jakiego satyra. Skalp musi pochodzić ze skrytotropiciela Nienawistnej Furii.$B$BSzukaj ich wśród starożytnych ruin na północnym wschodzie Mrocznego Pustkowia.', 'Przynieś skalp skrytotropiciela Maurinowi Kościołupowi w Mrocznym Pustkowiu.', '', 'Wróć do Maurina Kościołupa na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1482, 'koKR', 'Plugawiciel', 'Kryształ wyroczni świetnie by się nadał. Wytwarzają je nagi dla swoich wyroczni.$B$BNa północny zachód stąd, wzdłuż wybrzeża, ciągnie się rozległa rafa koralowa, którą nagi obrały sobie za dom, gdy przebywają tak blisko brzegu. Tam znajdziesz ich wyrocznie. Nagi Wężowego Ostrza są śmiertelnie groźne i nie przyjmą życzliwie twojego wtargnięcia, więc uważaj i się pośpiesz.$B$BGdy wrócisz, zajmiemy się szukaniem tego demonicznego lorda Azrethoca.', 'Przynieś kryształ wyroczni Maurinowi Kościołupowi w Mrocznym Pustkowiu.', '', 'Wróć do Maurina Kościołupa na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', 0),
(1484, 'koKR', 'Plugawiciel', 'Ta istota jest znacznie groźniejsza, niż przewidywałem. Takata z pewnością wątpi, czy potrafię zmierzyć się z takim stworem, a gdyby nie dowiedział się, co się przed chwilą stało, uraziłoby to jego honor.$B$BPorozmawiaj z szermierzem, powiedz mu, że chcesz zgładzić demona, jeśli na to pozwoli, ale zbytnio nie naciskaj. Lepiej, żeby uznał to za własny pomysł.', 'Porozmawiaj z Takatą Stalowym Ostrzem na Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1488, 'koKR', 'Plugawiciel', 'Choć nic nie wiem o tym lordzie Azrethocu, zgadzam się z Maurinem – trzeba go powstrzymać, zwłaszcza jeśli próbuje zdobyć wpływy w Płonącym Ostrzu, by osiągnąć własne cele.$B$B$GPokazałeś:Pokazałaś; już, że chcesz pomagać wodzowi, więc powierzyłbym ci zebranie drużyny, która zgładzi demonicznego lorda i jego sługę czarnoksiężnika.$B$BGdy będziesz $ggotów:gotowa;, ruszaj prosto na południe i wróć do mnie, gdy zagrożenie zostanie zażegnane.', 'Zabij lorda Azrethoca i Jugkara Grim\'roda, a następnie wróć do Takaty Stalowego Ostrza w Mrocznym Pustkowiu.', '', 'Wróć do Takaty Stalowego Ostrza w Posterunku Chodzącego z Duchami na Mrocznym Pustkowiu.', '', '', '', '', 0),
(5381, 'koKR', 'Ręka Iruxosa', 'Płonące Ostrze ma demoniczną skrzynkę. W niej spoczywa potężna Ręka Iruxosa. Płonące Ostrze używa jej, by otwierać demoniczne portale w Sabacie Mannoroca. Musimy powstrzymać falę demonów napływających do naszego świata, $n!$B$BUżyj tego demonicznego kilofa na czerwonym krysztale w Fortecy Gromowego Topora, aby dostać się do demonicznej skrzynki.$B', 'Zdobądź demoniczną skrzynkę z Fortecy Gromowego Topora i zanieś ją wraz z demonicznym kilofem Taidze Mądrogrzywemu w Wiosce Cienistej Ofiary.$B', '', 'Wróć do Taigi Mądrogrzywego w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', '', '', '', '', 0),
(5386, 'koKR', 'Połów dnia', 'Tu, na Posterunku Chodzącego z Duchami, od dawna brakuje zapachu smażonej ryby. Trolle z Wioski Cienistej Ofiary łowią ryby najlepiej... ale niestety, przy całym tym zamieszaniu z centaurami nie mam czasu na wyprawę do trolli. Hmm...$B$BZrób mi przysługę i wybierz się do Wioski Cienistej Ofiary. Porozmawiaj z tamtejszym rybakiem Jinar\'Zillenem i przynieś mi moje ulubione ryby krwawobrzuche. Droga na południe stąd zaprowadzi cię na zachód, do wioski trolli.', 'Porozmawiaj z Jinar\'Zillenem w Wiosce Cienistej Ofiary, a następnie przynieś Natace Długorogiemu 2 ryby krwawobrzuche.', '', 'Wróć do Nataki Długi Róg na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', 0),
(5421, 'koKR', 'Ryba w wiadrze', '', '', '', 'Wróć do Jinar\'Zillena w Mrocznym Pustkowiu.', '', '', '', '', 0),
(5501, 'koKR', 'Kolekcjoner kości', 'Siedzimy tu na żyle złota, mówię ci – na żyle złota! Kości kodo na zawsze odmienią świat... Mam klientów, którzy robią z nich meble, instrumenty muzyczne, a nawet proch strzelniczy.$B$BPrzejeżdża tędy karawana, która zabiera moje kości kodo, a potem sprzedaje je w Wiosce Cienistej Ofiary. Jeśli wybierzesz się na cmentarzysko kodo na południe stąd i przyniesiesz mi dziesięć kości kodo, dam ci coś w zamian. Umowa stoi?', 'Przynieś 10 kości kodo z Cmentarzyska Kodo Bibbly\'emu F\'utzbuckle\'owi w Chatce Kormeka.', '', 'Wróć do Bibbly\'ego F\'utzbuckle\'a w Mrocznym Pustkowiu.', '', '', '', '', 0),
(5561, 'koKR', 'Spęd kodo', 'Bibbly myśli, że jest jedynym goblinem w Mrocznym Pustkowiu, który umie zarabiać pieniądze. Otóż jedyna karawana, która ma odwagę jeździć po tych stronach, polega na mnie. Odkąd nauczyłem się odmładzać i kontrolować stare i umierające kodo moim kodokombobulatorem, ja, właściciel karawany Cork i Rigger jesteśmy wspólnikami.$B$BWeź kombobulator i użyj go na dowolnym sędziwym, starym lub umierającym kodo; wstrząs zmieni bestię w oswojonego kodo i zmusi ją, by szła za tobą. Gdy już oswoisz kodo, przyprowadź go do mnie.', 'Przyprowadź pięć oswojonych kodo i odnieś kodokombobulator Smeedowi Scrabblescrewowi w Obozie Scrabblescrewa.', '', 'Wróć do Smeeda Scrabblescrewa w Obozie Scrabblescrewa w Mrocznym Pustkowiu.', 'Oswojone kodo', '', '', '', 0),
(5581, 'koKR', 'Portale Legionu', 'Oto Ręka Iruxosa. Doprawdy makabryczny widok.$B$BMusisz ją mieć przy sobie, jeśli demoniczne portale w Sabacie Mannoroca mają zostać wygnane... i właśnie o to cię teraz proszę. Zagrożenie ze strony demonów rośnie i musimy zamknąć te portale, by powstrzymać napływ demonów do tego świata. Powodzenia, $N... i strzeż się strażników portali.$B', 'Wygnaj 6 portali w Sabacie Mannoroca i wróć do Taigi Mądrogrzywego w Wiosce Cienistej Ofiary.$B', '', 'Wróć do Taigi Mądrogrzywego w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', 'Wygnane portale', '', '', '', 0),
(5741, 'koKR', 'Berło Światła', 'Podobno Płonące Ostrze w Fortecy Gromowego Topora na wschodzie zdobyło od nag Berło Światła. Legenda głosi, że berło potrafi zatopić całe miasta w głębinach wielkich mórz. Nie wolno dopuścić, by Płonące Ostrze władało taką mocą.$B$BDlatego musisz osobiście odzyskać berło! Ma je jasnowidz Płonącego Ostrza, który bada je na szczycie jednej ze strażnic Gromowego Topora.$B', 'Zdobądź Berło Światła i zanieś je Azore\'owi Aldamortowi do wieży w Ethel Rethor.$B', '', 'Wróć do Azore\'a Aldamorta w Ethel Rethor w Mrocznym Pustkowiu.', '', '', '', '', 0),
(5763, 'koKR', 'Łowy w Cierniodławach', 'Dawno temu przybył do tej krainy pewien krasnolud. Nazywał się Hemet i pragnął polować na wielkie bestie. Władał strzelbą z niesamowitą wprawą, a my spędziliśmy wiele dni na wspólnych łowach. Zapomnieliśmy nawet o wrogości między naszymi ludami.$B$BGdy wyruszał do Cierniodławów, przysiągłem sobie, że pewnego dnia znów go tu powitam. Teraz wyruszył na łowy do nieznanych krain, ale jego miejsce zajął syn.$B$BZanieś ten róg kodo w darze Hemetowi juniorowi. Znajdziesz go w Cierniodławach, na północ od Obozu Grom\'gol.', 'Zanieś róg kodo Roona Hemetowi Nesingwary\'emu juniorowi w Dolinie Cierniodławów.', '', '', '', '', '', '', 0),
(5821, 'koKR', 'Ochroniarz do wynajęcia', 'W normalnych warunkach Rigger i ja po prostu przeprowadzilibyśmy nasze kodo obok centaurów Kolkarów. Co jakiś czas słyszymy jednak bębny wojenne centaurów, a kiedy je słyszymy, stajemy. Bycie martwym nie służy interesom!$B$BWiesz co, $N, jeśli ochronisz nas w drodze obok Wioski Kolkarów, opłaci ci się to.$B$BTo tylko kawałek, wystarczy, że karawana dotrze w całości, a nagrodę odbierzesz u Smeeda Scrabblescrewa – jest kawałek dalej przy drodze. Robimy razem małe interesy.', 'Eskortuj Karawanę Gizeltona obok wioski centaurów Kolkarów. Po nagrodę zgłoś się do Smeeda w Obozie Scrabblescrewa.', 'Eskortuj Karawanę Gizeltona obok wioski centaurów Kolkarów', 'Wróć do Smeeda Scrabblescrewa w Obozie Scrabblescrewa w Mrocznym Pustkowiu.', '', '', '', '', 0),
(5943, 'koKR', 'Karawana Gizeltona', 'Wyglądasz mi na kogoś, kto zna się na rzeczy. Może chcesz trochę zarobić? Cork i ja założyliśmy tę karawanę, żeby zbić fortunę; nie mieliśmy pojęcia, jak niebezpieczne jest dorabianie się!$B$BPrzed nami leży Sabat Mannoroca... zwykle demony nie zwracają na nas uwagi, ale tym razem coś spłoszyło kodo. Zapłacę ci za ochronę karawany w drodze przez Sabat Mannoroca. Gdy będziemy bezpieczni po drugiej stronie, nagrodę odbierzesz od naszego wspólnika Smeeda w Obozie Scrabblescrewa.', 'Eskortuj Karawanę Gizeltona przez Sabat Mannoroca. Po nagrodę zgłoś się do Smeeda w Obozie Scrabblescrewa.', 'Eskortuj Karawanę Gizeltona przez Sabat Mannoroca', 'Wróć do Smeeda Scrabblescrewa w Obozie Scrabblescrewa w Mrocznym Pustkowiu.', '', '', '', '', 0),
(6027, 'koKR', 'Księga Pradawnych', '$n, powierzam ci klejnot węża. Umieść go w dłoni posągu węża na Wyspie Ranazjar, małej wysepce na północny zachód stąd. Klejnot przywoła tego, kto strzeże Księgi Pradawnych. Ta księga zawiera sekrety nag, strzeżone od stuleci. Przynieś mi ją, a dowiemy się wiele o naszych łuskowatych wrogach!', 'Zdobądź Księgę Pradawnych i zanieś ją Azore\'owi Aldamortowi do wieży w Ethel Rethor.$B', '', 'Wróć do Azore\'a Aldamorta w Ethel Rethor w Mrocznym Pustkowiu.', '', '', '', '', 0),
(6132, 'koKR', 'Wyciągnij mnie stąd!', 'Wyciągnij mnie stąd!$B$BPrzyszłam do Doliny Włóczni, żeby porozmawiać z Maraudine. Myślałam, że zrobię z nimi mały interes... ale oni nie chcą rozmawiać! Chyba chcą mnie zjeść!$B$BWyciągnij mnie stąd, a mój brat Hornizz sowicie ci zapłaci! Jest w naszym obozie obok cmentarzyska kodo, na wschodzie.$B$BPośpieszmy się, $N. Niecałe dwie minuty temu słyszałam, jak jakieś centaury rozmawiały o zbieraniu drewna pod kocioł...', 'Eskortuj Melizzę Brimbuzzle, a następnie porozmawiaj z Hornizzem Brimbuzzle na Cmentarzysku Kodo w Mrocznym Pustkowiu.', 'Melizza Brimbuzzle doprowadzona w bezpieczne miejsce', 'Wróć do Hornizza Brimbuzzle w Mrocznym Pustkowiu.', '', '', '', '', 0),
(6134, 'koKR', 'Łapanka duchoplazmy', 'Na południowym wschodzie jest dolina, Dolina Kości, nawiedzana przez duchy Magram. Brzmi strasznie, co? No to pomyśl, jak straszne to jest dla Magram! Gdybyśmy złapali trochę duchowej energii z tamtego miejsca, założę się, że te centaury dużo by za nią dały.$B$BMasz, weź tę skrzynkę magnesów na duchy. Jeśli postawisz jeden między dwoma wielkimi szkieletami w dolinie, Martwymi Goliatami, duchy same do niego przywędrują. Odsuń się, rozpraw się z duchami i zbierz ich duchoplazmę – to właśnie sprzedamy Magram.', 'Przynieś 8 porcji duchoplazmy i skrzynkę magnesów na duchy Hornizzowi Brimbuzzle w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(6142, 'koKR', 'Przynęta z małży', 'Wyglądasz mi na $gwędkarza:wędkarkę;, $N! Uwielbiam łowić ryby – łowię całe życie. Najlepsza przynęta to mięso miękkoskorupowych małży; ryby po prostu nie mogą mu się oprzeć, wiesz, o co chodzi?$B$BNa północy, przy wybrzeżu, znajdziesz wrak statku. W całej okolicy pełno jest miękkoskorupowych małży. Jeśli przyniesiesz mi 10 kawałków mięsa miękkoskorupowej małży, dam ci coś w zamian.', 'Znajdź 10 kawałków mięsa miękkoskorupowej małży i zanieś je Mai\'Lahii w Wiosce Cienistej Ofiary.', '', 'Wróć do Mai\'Lahii w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', '', '', '', '', 0),
(6143, 'koKR', 'Inne ryby do usmażenia', 'Może $gsłyszałeś:słyszałaś;, a może nie... ja i moja załoga łowiliśmy ryby przy Wyspie Ranazjar, na północ od wraku statku u północnego wybrzeża. Łowiliśmy tam cały czas; a teraz myślę tylko o tym, jak pomścić moich poległych kompanów.$B$BPewnego ranka nagi nas zaatakowały i zabiły wszystkich oprócz mnie.$B$BMoje sumienie nie zniesie tej winy, $N; musisz iść i usmażyć dla mnie te nagi. Wynagrodzę ci trud; myślisz, że mi w tym pomożesz?', 'Zabij 7 siepaczy Wężowego Ostrza, 7 nag Wężowego Ostrza i 5 czarodziejek Wężowego Ostrza, a następnie porozmawiaj z Drulzegarem w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', '', 'Wróć do Drulzegara Skraghooka w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', '', '', '', '', 0),
(6161, 'koKR', 'Zdobądź skarb Rackmore\'a!', 'Dziennik Rackmore\'a opisuje, jak jego statek płynął do Warowni Lunopiórej, gdy zaatakowały go morskie stwory. Aby jego skarb nie wpadł w ręce wroga, ukrył skrzynię na Wyspie Ranazjar.$B$BDo otwarcia skrzyni potrzeba dwóch kluczy, srebrnego i złotego. Klucze zaginęły, ale jeśli odnajdzie się je i skrzynię, czeka skarb!', 'Znajdź srebrny klucz Rackmore\'a. Znajdź złoty klucz Rackmore\'a. Znajdź i otwórz skrzynię Rackmore\'a.', '', 'Wróć do skrzyni Rackmore\'a na Wybrzeżu Sar\'theris w Mrocznym Pustkowiu.', '', '', '', '', 0),
(6568, 'koKR', 'Mistrzyni zwodzenia', 'Iluzja i przebranie. Tak oszukasz Czarne Stado i zdobędziesz to, czego szukasz.$b$bChoć mógłbym nauczyć cię co nieco sztuki zwodzenia, potrzebujesz pomocy mistrza.$b$bZnam kogoś, kto mógłby to zrobić. Na Zachodnich Plagowiskach znajdziesz Myrandę Jędzę, niegdyś mistrzynię iluzji z Lordaeronu. Pomagała nam w przeszłości i jeśli uzna sprawę za godną, może pomóc i tobie.$b$bZanieś jej tę wiadomość.', 'Dostarcz list Rokaro Myrandzie Jędzy na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(6601, 'koKR', 'Wniebowstąpienie...', 'Z czaszek naszych wrogów ukształtowano medalion. Znasz ten medalion, prawdaaa? Bez wątpienia nosiła go twoja starszyzna.$B$BWeź go, pisklaku. Wróć do Iglicy i przedstaw go generałowi Drakkisatowi. Generał nałoży na medalion ostateczne zaklęcie, dostrajając go do twojego ducha.$B$BBędziesz nosić gotowy medalion jako odznakę honoru, symbol twojego wyniesienia do jednej z naszych najpilniej strzeżonych rang: Strażnika matki miotu.$B$BIdź!', 'Wygląda na to, że maskarada się skończyła. Wiesz, że amulet smoczej wywrotowości, który stworzyła dla ciebie Myranda Jędza, nie zadziała w Iglicy Czarnej Góry. Może warto odnaleźć Rokaro i wyjaśnić mu swoje położenie. Pokaż mu matowy amulet smoczego ognia. Miejmy nadzieję, że będzie wiedział, co dalej.', '', '', '', '', '', '', 0),
(6602, 'koKR', 'Krew czempiona czarnych smoków', 'Co powiesz na wizytę u generała? Tym razem bez iluzji.$b$bCeremonia? Ładne słowo na upust krwi, który tak bawi Czarne Stado.$b$bTen amulet wymaga jedynie krwi generała Drakkisata. Prymitywne zabezpieczenie. Są inne sposoby, by zdobyć krew generała.$b$bUdaj się do Iglicy Czarnej Góry i zabij Drakkisata. Wróć z jego krwią, a aktywuję klucz do leża Onyxii.', 'Udaj się do Iglicy Czarnej Góry i zabij generała Drakkisata. Zbierz jego krew i zanieś ją Rokaro.', '', 'Wróć do Rokaro w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', '', '', '', '', 0),
(7028, 'koKR', 'Wypaczone zło', 'Kryształowe jaskinie Terramoku leżą na zachodzie, głęboko w Maraudonie... To starożytne miejsce o bogatej historii. A ja chcę położyć ręce na jej cząstce, $N. Za olbrzymimi wrotami leżą ukryte relikty Przedwiecznych.$B$BJeśli nie boisz się stawić czoła wypaczonemu złu, które czai się w Maraudonie, myślę, że sprawię, że ci się to opłaci. Zbieraj rzeźby z theradryckiego kryształu, które znajdziesz, i przynieś je do mnie.$B$BGdy dostanę rzeźby, będę mogła je... zbadać. Te moce zbyt długo pozostawały w uśpieniu...', 'Zbierz 15 rzeźb z theradryckiego kryształu dla Willow w Mrocznym Pustkowiu.', '', 'Wróć do Willow w Mrocznym Pustkowiu.', '', '', '', '', 0),
(7029, 'koKR', 'Splugawienie Podłojęzyka', 'Satyr zwany Podłojęzykiem splugawił jaskinie Maraudonu, hamując wzrost wielu rosnących w nich roślin.$B$BWeź tę fiolkę, $N. Napełnij ją w pomarańczowym kryształowym stawie wewnątrz jaskiń; powłoka wewnątrz fiolki zneutralizuje toksyny i zamieni wodę w środek leczniczy.$B$BZnajdź pnącza Vylestem w pomarańczowych jaskiniach i użyj na nich oczyszczonego płynu. Splugawienie zostanie wypędzone z roślin, ale wiedz, że Podłojęzyk wciąż będzie nad nimi panował. Może użyć ich przeciwko tobie...', 'Napełnij powleczoną lazurową fiolkę w pomarańczowym kryształowym stawie w Maraudonie.$B$BUżyj napełnionej lazurowej fiolki na pnączach Vylestem, aby zmusić splugawionego trującego potomka do wyjścia.$B$BUlecz 8 roślin, zabijając trujących potomków, a następnie wróć do Varka Blizny Wojny w Wiosce Cienistej Ofiary.', '', 'Wróć do Varka Blizny Wojny w Wiosce Gelkis w Mrocznym Pustkowiu.', 'Uleczone pnącza Vylestem', '', '', '', 0),
(7041, 'koKR', 'Splugawienie Podłojęzyka', 'Satyr zwany Podłojęzykiem splugawił jaskinie Maraudonu, hamując wzrost wielu rosnących w nich roślin.$B$BWeź tę fiolkę, $N. Napełnij ją w splugawionym pomarańczowym stawie wewnątrz jaskiń; powłoka wewnątrz fiolki zneutralizuje toksyny i zamieni wodę w środek leczniczy.$B$BZnajdź pnącza Vylestem w pomarańczowych jaskiniach i użyj na nich oczyszczonego płynu. Splugawienie zostanie wypędzone z roślin, ale wiedz, że Podłojęzyk wciąż będzie nad nimi panował. Może użyć ich przeciwko tobie...', 'Napełnij powleczoną lazurową fiolkę w pomarańczowym kryształowym stawie w Maraudonie.$B$BUżyj napełnionej lazurowej fiolki na pnączach Vylestem, aby zmusić splugawionego trującego potomka do wyjścia.$B$BUlecz 8 roślin, zabijając trujących potomków, a następnie wróć do Talendrii w Punkcie Nijela.', '', 'Wróć do Talendrii w Zwęglonej Dolinie w Górach Szponogłazach.', 'Uleczone pnącza Vylestem', '', '', '', 0),
(7044, 'koKR', 'Legendy Maraudonu', 'Mroczny satyr zwany lordem Podłojęzykiem rozsiał swoje zło po tych krętych jaskiniach, zatruwając umysły wszystkich, którzy tu są. Wciąż przebywa za fioletowymi kryształami.$B$BPodłojęzyk stworzył też żywy symbol swojego splugawienia, zwany Noxxionem, który mieszka za pomarańczowymi kryształami. Razem ukradli dwie części berła mojego brata. Celebras, mój brat... błąka się na oślep w głębi jaskiń, przeklęty przez splugawienie.$B$BMusisz mu pomóc! Odnajdź części i porozmawiaj z moim bratem... jakoś.', 'Odzyskaj dwie części Berła Celebrasa: celebriańską różdżkę i celebriański diament.$B$BZnajdź sposób, by porozmawiać z Celebrasem.', '', 'Wróć do Celebrasa Odkupionego nad Jeziorem Lordamere w Srebrzystym Borze.', '', '', '', '', 0),
(7046, 'koKR', 'Berło Celebrasa', 'Moje berło było niegdyś dla mnie źródłem nadziei. Dawało mi władzę nad tymi jaskiniami. Miałem nadzieję, że przyniosę spokój duchowi mojego wuja...$B$BAby obie części znów stały się jednością, potrzebuję twojej pomocy w odprawieniu rytuału. Proszę, podążaj za mną i słuchaj moich wskazówek, gdy będę przywoływał energię potrzebną do ponownego połączenia różdżki z diamentem.$B$BRazem raz jeszcze stworzymy Berło Celebrasa!', 'Pomóż Celebrasowi Odkupionemu, gdy będzie tworzył Berło Celebrasa.$B$BPorozmawiaj z nim po zakończeniu rytuału.', 'Stwórz Berło Celebrasa', 'Wróć do Celebrasa Odkupionego nad Jeziorem Lordamere w Srebrzystym Borze.', '', '', '', '', 0),
(7064, 'koKR', 'Splugawienie ziemi i nasienia', 'W głębi Maraudonu żyje zła istota chaosu – księżniczka Theradras, żywiołowa siła ziemi spokrewniona z Przedwiecznymi. Przed wiekami ona i Zaetar, pierworodny syn Cenariusa, związali się ze sobą. Potomstwo z ich związku ludy Kalimdoru poznały jako centaury. Wdzięczne jak zawsze centaury zabiły Zaetara i teraz przetrzymują jego szczątki. Moją misją jest odnaleźć tych, którzy są dość potężni, by zabić Theradras, abyśmy mogli odzyskać szczątki Zaetara przed powrotem w Góry Szponogłazy.', 'Zabij księżniczkę Theradras i wróć do Selendry w pobliżu Wioski Cienistej Ofiary w Mrocznym Pustkowiu.', '', 'Wróć do Selendry na Wybrzeżu Sar\'theris w Mrocznym Pustkowiu.', '', '', '', '', 0),
(7065, 'koKR', 'Splugawienie ziemi i nasienia', 'W głębinach Maraudonu żyje istota chaosu i zła, $N. Księżniczka Theradras to żywiołowa siła ziemi w jakiś sposób spokrewniona z Przedwiecznymi. Przed wiekami odszukał ją Zaetar, pierworodny syn Cenariusa. Potomstwo z ich... związku to istoty zwane centaurami. Wdzięczne jak zawsze centaury zabiły Zaetara, a teraz Theradras strzeże jego szczątków. Moją misją jest odnaleźć tych, którzy są dość potężni, by zabić Theradras, abyśmy mogli odzyskać szczątki Zaetara przed powrotem w Góry Szponogłazy.', 'Zabij księżniczkę Theradras i wróć do opiekuna Marandisa w Punkcie Nijela w Mrocznym Pustkowiu.', '', 'Wróć do opiekuna Marandisa w Mrocznym Pustkowiu.', '', '', '', '', 0),
(7067, 'koKR', 'Instrukcje pariasa', 'Choć wygnano mnie jako heretyka, moje przekonania wciąż są słuszne – i tylko to pcha mnie naprzód. Lecz aby moje przeznaczenie się dopełniło, potrzebuję pomocy kogoś z zewnątrz... kogoś, kto nie należy do żadnego plemienia centaurów.$B$BTo zadanie wymaga, by ktoś wszedł do świętych sal Maraudonu – grobowca, którego strzeże mój lud i do którego wstęp mają tylko najpobożniejsi.$B$BJeśli zgadzasz się mi pomóc, wystarczy, że skiniesz głową. Podam ci pergamin z moimi instrukcjami. Przeczytaj go i rozważ moje słowa.', 'Przeczytaj instrukcje pariasa. Następnie zdobądź w Maraudonie amulet jedności i zanieś go centaurowi pariasowi w południowej części Mrocznego Pustkowia.', '', 'Wróć do centaura pariasa przy Bliźniaczych Kolosach w Feralas.', '', '', '', '', 0),
(8458, 'koKR', '', 'Sądzę, że zdołam odnaleźć tego demonicznego lorda, jeśli dostanę właściwe składniki.$B$BJeśli rzeczywiście jest tak potężny, jak podejrzewam, będę potrzebował przedmiotów zdobytych na śmiertelnie groźnych stworzeniach. Ale działasz w imieniu wodza, więc jestem pewien, że przyjmiesz moje zadanie.$B$BNajpierw będę musiał przełamać wszelkie osłony, jakimi chroni się przed wieszczeniem. Do tego potrzebuję skalpu satyra – ale nie byle jakiego satyra. Skalp musi pochodzić ze skrytotropiciela Nienawistnej Furii.$B$BSzukaj ich wśród starożytnych ruin na północnym wschodzie Mrocznego Pustkowia.', 'Przynieś skalp skrytotropiciela Maurinowi Kościołupowi w Mrocznym Pustkowiu.', '', 'Wróć do Maurina Kościołupa na Posterunku Chodzącego z Duchami w Mrocznym Pustkowiu.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(261, 'koKR', '$GDowiodłeś:Dowiodłaś; swojej determinacji, a Szkarłatna Krucjata wyraża ci uznanie.$B$BJeśli nie cofasz się przed sprawiedliwą rzezią, być może twoja ścieżka wiedzie ku nam...', 0),
(1365, 'koKR', 'Dobra robota. Ten szybki cios wymierzony w Kolkarów to skuteczny pokaz siły, a siłę centaury rozumieją najlepiej.$B$BŚmierć przywódcy Kolkarów nie tylko wprowadzi zamęt w tym klanie, ale da też do myślenia pozostałym.', 0),
(1366, 'koKR', 'Centaury muszą już znać twoje imię. Jestem pewien, że je znają, szanują je i się go boją. A skoro znają ciebie, znają też sztandar, pod którym walczysz.$B$BSztandar Hordy.', 0),
(1367, 'koKR', 'Gelkis płaczą, gdy słyszą twoje imię, $N. Boją się ciebie i cię nienawidzą. Nienawidzą cię tak, jak nienawidzą Magram!$b$bMoże jesteś $gsilny:silna; jak Magram. Zobaczymy...', 0),
(1368, 'koKR', 'Ziemia do mnie mówi. A mówi, że z twojej ręki zginęło wielu Magram. To dobrze.$B$BJeśli jesteś $gprzyjacielem:przyjaciółką; Gelkis, to słuchaj. Mam dla ciebie więcej zadań.', 0),
(1369, 'koKR', 'Masz łzy! Teraz Gelkis będą wiedzieć, że Theradras im nie pomoże. Nie zapłacze, gdy ich zmiażdżymy! Magram będą rządzić!$B$BMądrze robisz, że nam pomagasz, $N. Jesteśmy najsilniejsi.', 0),
(1370, 'koKR', 'Dobrze. Słyszę, jak głośno burczą brzuchy Magram w ich wiosce, daleko stąd!$B$BDam to mięso Gelkis. I będziemy walczyć wiele dni bez odpoczynku.$B$BTo, co $gzrobiłeś:zrobiłaś;, jest dobre dla Gelkis, $N.', 0),
(1371, 'koKR', 'Tak, właśnie to miałem! Sprawię, że znów będzie się ruszać. To mnie śmieszy!', 0),
(1373, 'koKR', 'Tak, to jest odłamek, o którym szeptała ziemia. Czuję w nim silną magię! Użyję tej magii przeciw wrogom Gelkis.$B$B$GWykonałeś:Wykonałaś; dla nas jeszcze jedno zadanie, $N. Może niedługo nazwiemy cię przyjacielem.', 0),
(1374, 'koKR', 'Chan Jehn był silny, ale głupi. Myślał, że jego siła jest wielka. Nie widział, że magia ziemi jest silniejsza. Centaury Magram upadną teraz bez przywódcy, a Gelkis pewnego dnia będą rządzić!', 0),
(1375, 'koKR', 'Chan Shaka nie żyje! Nabiję jego głowę na pikę i będę ją trzymał przy sobie, żeby Shaka widział siłę Magram!', 0),
(1380, 'koKR', 'Nie żyje! Chan Hratha nie żyje! Teraz Maraudine upadną! Gdy Gelkis będą rządzić tą ziemią, $N, zapamiętamy cię. A duchy ziemi będą śpiewać twoje imię po wsze czasy.', 0),
(1381, 'koKR', 'Chan Hratha nie żyje! Teraz Magram są najsilniejsi z centaurów! Zmiażdżymy pozostałych i będziemy rządzić Mrocznym Pustkowiem!$B$BZapamiętamy cię, $N, i oszczędzimy ci naszych kopyt, gdy stratujemy wszystkich innych.', 0),
(1382, 'koKR', 'Twoje imię szepcze się wśród Gelkis. Masz na rękach dużo krwi Magram. To dobrze.$B$BMoże dobrze też, żebyśmy porozmawiali. Porozmawiajmy o tym, co możesz zrobić dla Gelkis i co my możemy zrobić dla ciebie.', 0),
(1384, 'koKR', 'Dobrze robisz dla Gelkis. Kolkarowie są słabi i zginą. Ich magia jest żałosna i ich nie ocali. $GPokazałeś:Pokazałaś; im to, a strach uczyni ich jeszcze słabszymi!$B$BA na naszych ziemiach słabi szybko giną.', 0),
(1385, 'koKR', 'Wielu Gelkis pada z twojej ręki. Podoba mi się to. Może możesz zrobić więcej rzeczy, które mi się spodobają. Może ty i Magram możecie być przyjaciółmi.', 0),
(1386, 'koKR', 'Kolkarowie teraz się ciebie boją! Mam nadzieję, że $gśmiałeś:śmiałaś; się, gdy ich $gzabijałeś:zabijałaś;. Lepiej się śmiać, gdy się zabija, żeby wróg widział, że jest słaby.', 0),
(1387, 'koKR', 'Ach, uszy. Dobra robota.$B$BTwoja służba dla Przymierza jest bez zarzutu, $N. Krew, którą $gprzelałeś:przelałaś; w Mrocznym Pustkowiu, bez wątpienia ocali niezliczone życia.', 0),
(1437, 'koKR', 'Gdy przetrząsasz szczątki wozu, staje się jasne, że zaatakowano go zarówno zaklęciami, jak i bronią. Walka była chyba jednostronna i krótka; nie ma śladów krwi ani żadnych ciał.$B$BKtokolwiek napadł na wóz, działał sprawnie i szybko.', 0),
(1438, 'koKR', 'Dzięki Elunie, że ktoś wreszcie przyszedł z pomocą. Proszę, $N, potrzebuję twojej pomocy. Mnie i mojego brata Tyranisa pojmało i sprowadziło tu Płonące Ostrze. Chyba chcą mnie złożyć w ofierze swoim demonicznym panom!$B$BWiedziałam, że przyjazd do Mrocznego Pustkowia to błąd, ale Tyranis od niedawna łaknie wiedzy o wszystkim, co tajemne – nawet wbrew woli naszego ludu. Postanowił wyruszyć w tę podróż, choć słyszał opowieści o demonach, od których roi się w tej krainie.$B$BObawiam się o niego jak najgorzej.', 0),
(1439, 'koKR', 'To straszne! Ale chyba było to konieczne. Gdyby nie zginął z twojej ręki, z pewnością zginąłby z ręki mojego ludu. Powinnam ci chyba podziękować – wybacz, proszę, jeśli nie zabrzmi to szczerze. Nie chcę cię urazić.$B$BSkoro wiem już, jaki los spotkał mojego brata, przyszła chyba pora na moją ucieczkę. Jeśli wciąż chcesz mi pomóc, przyjmę twoją pomoc w ucieczce z tego okropnego miejsca.$B$BGdy będziesz $ggotów:gotowa;, możemy ruszać w bezpieczne miejsce.', 0),
(1440, 'koKR', 'Dziękuję ci, $N. Dalinda dotarła bezpiecznie tu, do Punktu Nijela, i to w znacznie lepszym stanie, niż mogłem się spodziewać. To, że przyszła o własnych siłach, było dobrym znakiem. Mam nadzieję, że i u ciebie wszystko w porządku?$B$BBoli mnie, że Tyranis nie wrócił razem z Dalindą, ale wstyd za jego decyzje musi znieść ona sama. Będzie musiała się z tym zmierzyć po powrocie do Darnassus.', 0),
(1454, 'koKR', 'Zauważasz, że skrzynia nie wygląda na uszkodzoną przez wodę.$B$BDruga rzecz, którą zauważasz, to wyłamane wieko; wszelkie magiczne pułapki, które miały jej strzec, dawno już zadziałały – świadczą o tym ślady spalenizny wokół krawędzi.', 0),
(1455, 'koKR', 'Witaj z powrotem w Punkcie Nijela, $N. No, mów, co $gznalazłeś:znalazłaś;.$B$BCo!? Nic? Obawiam się, że za pustą skrzynię nikt nam nie zapłaci.$B$BOpowiedz mi więcej o tych śladach, które $gwidziałeś:widziałaś;... o tych nacięciach.', 0),
(1456, 'koKR', 'Świetnie, $N! $GZnalazłeś:Znalazłaś; rzeczy Karnitola!$B$BTe przeklęte nagi, wiecznie tylko kłopoty. Chyba wolałbym spędzić życie na wojnie z Hordą, niż mierzyć się z ich pobratymcami. $GOddałeś:Oddałaś; Odzyskiwaczom wielką przysługę.', 0),
(1458, 'koKR', 'Dobrze, dobrze, $N. Nie wiem, czy są dobrej jakości, ale jeśli Leftwitch chciał jakiegoś konkretnego rodzaju, to trzeba było to powiedzieć, zanim wysłał tu Odzyskiwaczy.$B$BCo ty na to, żebyśmy wzięli się za następną pozycję z jego listy?', 0),
(1459, 'koKR', 'Twoja pomoc to dar niebios, $N. Dzięki tobie spędzę w Mrocznym Pustkowiu co najmniej o połowę mniej czasu. Z twoją pomocą ani się obejrzę, a będę z powrotem w Żelaznej Kuźni grzać sobie stopy.$B$BJak załatwimy tę listę i wrócę do domu, odwiedź mnie, na pewno postawię ci piwo.$B$BAle do tego czasu zbierzmy resztę tych składników.', 0),
(1465, 'koKR', 'To doprowadza mnie do szału! Cała ta kompromitacja!$B$BOstrzegano ich oboje, jak niebezpieczna jest podróż w te strony. Teraz oboje zaginęli... albo gorzej.$B$BMówisz, że $gwidziałeś:widziałaś; ślady prowadzące do pobliskiego fortu? To może być nasz najlepszy trop.$B$BWedług miejscowych w tej fortecy roi się od członków Płonącego Ostrza – orków, którzy oddali się sprawie demonów. Może nie reprezentują przekonań większości Hordy, ale są źli i zabiją cię na miejscu, jeśli przyłapią cię na szpiegowaniu.', 0),
(1466, 'koKR', 'Szczerze? Nie pomyślałbym. Jesteś $gniesamowity:niesamowita;, $N. Walczyć z demonami dla eksperymentów jakiegoś maga i jeszcze wrócić w jednym kawałku. Świetna robota!$B$BJak wrócę do Żelaznej Kuźni, osobiście opowiem o tobie Roettenowi.', 0),
(1480, 'koKR', 'Hmm, te runy to rzeczywiście język, $N, stary język. Przypominają z daleka język eredun, ale różnice są ogromne. Jeśli się nie mylę, to jakiś rodzaj kontraktu... O, tutaj, tak, ten symbol to podpis demona: lord Azrethoc.', 0),
(1481, 'koKR', 'Skrytotropiciele nie zdołali cię zabić, $N. Imponujące... nader imponujące.$B$BTen skalp świetnie się nada do mojego zaklęcia. Pod twoją nieobecność udało mi się zebrać część pozostałych składników potrzebnych do czaru.$B$BJestem już prawie gotów. Potrzebuję jeszcze tylko przedmiotu, na którym skupię zaklęcie – czegoś, co ukaże obraz demonicznego lorda i miejsce jego pobytu.', 0),
(1482, 'koKR', 'Cenny kryształ wyroczni... nieskazitelny... piękny. W rzeczy samej.$B$BZaczniemy natychmiast. Odnalezienie tego demonicznego lorda powinno być naszą główną troską, a jego zgładzenie wymaga od nas najwyższej uwagi.$B$BCofnij się o krok, $N, i zobaczmy, czym jest ten demon i gdzie można go znaleźć.', 0),
(1484, 'koKR', 'Widziałem, co przed chwilą zaszło między Maurinem a demonicznym lordem. Ta istota, nawet jako zjawa, zdaje się mieć więcej mocy niż mój towarzysz czarnoksiężnik. Zastanawiam się, czy podoła on zadaniu i pokona potwora. Wódz lepiej by na tym wyszedł, gdybym poszedł sam, ale mam tu swoje obowiązki i okryłbym hańbą swój klan, gdybym je porzucił, by dla własnego honoru walczyć z tym złem.', 0),
(1488, 'koKR', 'Wielkie zwycięstwo dla nas wszystkich, $N. Radujmy się twoim sukcesem. Teraz wierzę, że nasza przyszłość w tym miejscu nie jest tak ponura, jak niegdyś sądziłem.$B$BDemony zostaną wybite, wysiłki Płonącego Ostrza spełzną na niczym, a my pewnego dnia może znów będziemy mieli miejsce, które bez obaw nazwiemy domem.', 0),
(5381, 'koKR', 'Ach, demoniczna skrzynka. Daj mi ją, $N, a otworzę ją... i tym samym ukażę ci Rękę Iruxosa.$b$b', 0),
(5386, 'koKR', 'Ratujesz mi życie, $N! Te ryby krwawobrzuche wyglądają tak dobrze, że prawie można by je zjeść na surowo.$B$B<Natace cieknie ślinka.>$B$BProszę – wybierz sobie jeden z tych przedmiotów jako zapłatę za ryby.', 0),
(5421, 'koKR', 'Słodko, mon, nie ma nic lepszego niż zrobiona robota, zwłaszcza gdy robi ją ktoś inny... co?', 0),
(5501, 'koKR', 'O, cudnie! Moje kości!$B$BNie mogę się doczekać, aż chłopaki w domu zobaczą moją twarz na okładce „Goblinsiębiorcy”. Będę najbogatszym goblinem na świecie... a mój nauczyciel wychowania fizycznego mówił, że nigdy do niczego nie dojdę.', 0),
(5561, 'koKR', '<Smeed Scrabblescrew zaczyna liczyć.>$b$bTrzy, cztery i pięć... znakomicie, proszę o pięć oswojonych kodo i dostaję pięć oswojonych kodo... Będę bogaty... tak, bardzo bogaty! Chciałbym zobaczyć zieloną gębę Bibbly\'ego, gdy usłyszy o moim sukcesie!', 0),
(5581, 'koKR', 'Należą ci się słowa uznania, $N. Twój wysiłek bardzo pomógł w walce z demonicznym zagrożeniem, a dzięki temu całe Azeroth jest bezpieczniejsze.', 0),
(5741, 'koKR', 'Nieuchwytne Berło Światła! Zdobywając je, $gusunąłeś:usunęłaś; poważne zagrożenie dla świata. Dobra robota, $N, dobra robota.', 0),
(5763, 'koKR', 'Ach, ten róg należy do taurena, Roona Dzikogrzywego. Ojciec często opowiadał o dobrych czasach, gdy razem polowali na bestie Mrocznego Pustkowia. Czyli Roon zaprasza mnie do siebie, tak?$B$BTeraz siedzimy po uszy w dżungli, ale dziękuję ci, $N. Może następna wyprawa zaprowadzi mnie do Mrocznego Pustkowia, krainy centaurów.', 0),
(5821, 'koKR', 'Wiesz, płacenie takim jak ty za pilnowanie Karawany Gizeltona nie wygląda mi na dobry interes. $N, gdybym był odrobinę wyższy, wziąłbym drugą robotę, siadłbym bokiem na kodo z największą spluwą, jaką udźwignęłyby moje ręce... i pokazałbym tym przeklętym centaurom, kto tu rządzi.', 0),
(5943, 'koKR', 'Nie jestem pewien, czy płacenie takich pieniędzy za ochronę Karawany Gizeltona to dobry interes. Cork i Rigger zarabiają ledwie jedną sztukę złota na tydzień, ale dopóki płacą za moje kodo, nic mnie nie obchodzi, jak prowadzą swój interes.', 0),
(6027, 'koKR', 'Dawno zaginiona Księga Pradawnych! Dopilnuję, by trafiła do wysokiej rady. Dobrze się dziś $gspisałeś:spisałaś; i należą ci się za to podziękowania... takie, jakie należą się $gbohaterowi:bohaterce;!', 0),
(6132, 'koKR', 'Moja siostra Melizza mówiła, że przyjdziesz. Wielkie dzięki za wyciągnięcie jej z tarapatów; szkoda tylko, że pewnie już wpakowała się w nowe!', 0),
(6134, 'koKR', 'No i jest! Wygląda na to, że trochę się na ciebie ulało. Trochę oślizgłe, co?$B$BNo, wielkie dzięki za cały ten kłopot, $N. To będzie warte fortunę... jeśli zdołam przekonać centaury, co to jest!', 0),
(6142, 'koKR', 'Idealnie, mon, właśnie to kazał mi zrobić znachor na ból głowy. Mówi: „Mai\'Lahii, idź na ryby. Poczujesz się lepiej”.$B$BNo i już czuję się lepiej, dzięki, mon!', 0),
(6143, 'koKR', 'Choć słodko jest usłyszeć, że nagi zostały pokonane, moje serce wciąż jest puste. Resztę życia poświęcę na to, by je wszystkie wybić.$B$BMasz, mon, twoja nagroda, jak obiecałem. To niewiele w porównaniu z satysfakcją, że nagi się usmażyły za swój podły czyn wobec mojej załogi.', 0),
(6161, 'koKR', 'Skrzynia otwiera się, ukazując skarb Rackmore\'a!', 0),
(6568, 'koKR', '<Myranda trzyma liścik, waha się chwilę, po czym się uśmiecha.>$B$BCo u niego? U Rexxara, znaczy się. Och, daj spokój, nie rób takiej zdziwionej miny. List celowo zostawiono pusty. Niósł ze sobą zamiary i myśli swojego twórcy. Sądząc po jego treści, nic dziwnego, że Rexxar tak go zostawił. Wyobraź sobie, że $gzostałbyś schwytany albo zabity:zostałabyś schwytana albo zabita;, a te informacje wyszłyby na jaw!$B$BAch, mniejsza z tym! Myranda ci pomoże. Jestem winna wodzowi przysługę czy dwie.$B$B<Myranda się uśmiecha.>', 0),
(6601, 'koKR', 'To tylko smocze gadanie, $N – więcej gorącego powietrza niż rzeczowych informacji. Po ich rodzaju należy się spodziewać napuszonego, agresywnego zachowania.', 0),
(6602, 'koKR', 'Zwycięstwo, które będzie pamiętane przez wiele lat, $N. Amulet smoczego ognia otworzy leże Onyxii. Zbierz sojuszników i zapewnij Hordzie zwycięstwo.', 0),
(7028, 'koKR', 'Ha, ha, ha! Wiedziałam, że wrócisz.$b$b<Willow mamrocze>$b$b...Tak łatwo przekonać.$b$b...Za odpowiednią cenę zrobi wszystko. He, he, he...', 0),
(7029, 'koKR', 'Dziękuję, że to zwracasz, $N. Z resztą płynu, który mi $gprzyniosłeś:przyniosłaś;, mogę kontynuować badania.$b$bChoć wciąż jest wiele do zrobienia, $gpomogłeś:pomogłaś; uleczyć część splugawienia, które Podłojęzyk rozsiał po Maraudonie. Proszę, przyjmij to w podzięce.', 0),
(7041, 'koKR', 'Dziękuję, że to zwracasz, $N. Z resztą płynu, który mi $gprzyniosłeś:przyniosłaś;, mogę kontynuować badania.$b$bChoć wciąż jest wiele do zrobienia, $gpomogłeś:pomogłaś; uleczyć część splugawienia, które Podłojęzyk rozsiał po Maraudonie. Proszę, przyjmij to w podzięce.', 0),
(7044, 'koKR', 'Teraz, gdy $godzyskałeś:odzyskałaś; obie części mojego berła, mam nadzieję, że Maraudon pewnego dnia pozbędzie się tego podłego splugawienia.', 0),
(7064, 'koKR', 'To wspaniałe wieści, $N! Dziękuję!$b$bPorozmawiam z Marandisem i poproszę go o radę w sprawie szczątków Zaetara, ale przynajmniej $gpokonałeś:pokonałaś; najtrudniejsze z zadań.$b$bPowiedziano mi, że jeśli nasza misja się powiedzie, mogę nagrodzić tych, którzy nam pomogli. Otrzymałam te przedmioty jako dary od naszego ludu – możesz wybrać jeden.', 0),
(7065, 'koKR', 'To wspaniałe wieści, $N! Dziękuję!$B$BChoć martwi mnie, że nie $gzdołałeś:zdołałaś; przynieść szczątków Zaetara, kimże jestem, by kwestionować wolę pierworodnego Cenariusa. Być może teraz wola centaurów się złamie, a ich żądza krwi osłabnie – możemy tylko mieć nadzieję.$B$BDostałem te przedmioty, bym w razie powodzenia naszej misji nagrodził nimi tych, którzy nam pomogli. Możesz wybrać jeden jako wyraz wdzięczności.', 0),
(7067, 'koKR', 'To jest to! To jest to! Teraz mogę rozpocząć wielkie dzieło jednoczenia plemion. Dziękuję.$b$bProszę, weź to za swój trud. Mam nadzieję, że gdy spotkamy się następnym razem, okoliczności będą zupełnie inne.', 0),
(11741, 'koKR', 'Zbezcześć wielkie ognisko Przymierza w Mrocznym Pustkowiu!', 0),
(11769, 'koKR', 'Zbezcześć wielkie ognisko Hordy w Mrocznym Pustkowiu!', 0),
(11812, 'koKR', 'Uczcij płomień Mrocznego Pustkowia!', 0),
(11845, 'koKR', 'Uczcij płomień Mrocznego Pustkowia!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(261, 'koKR', 'Z każdym dniem Plaga rośnie w siłę. Jeśli naprawdę chcesz powstrzymać jej pochód, udowodnij mi to.', 0),
(1365, 'koKR', '$N, czy chan Dez\'hepah został pokonany?', 0),
(1366, 'koKR', 'Jak tam twoja kolekcja uszu, $N? Pokaźna?', 0),
(1367, 'koKR', 'Odejdź! Magram nie rozmawiają ze słabymi. My ich zabijamy!$B$BJeśli chcesz ze mną rozmawiać, pokaż mi, że masz siłę. Wróć, gdy zabijesz wielu Gelkis.', 0),
(1368, 'koKR', 'Twoje dwie stopy depczą ziemię Gelkis. Nie jesteś tu mile $gwidziany:widziana;!$B$BUdowodnij, że szukasz przyjaźni z Gelkis. Zabijaj centaury Magram. Wróć, gdy ziemia będzie mokra od krwi Magram.', 0),
(1369, 'koKR', 'Jeśli nie jesteś naszym wrogiem, zrobisz to, o co proszę!', 0),
(1370, 'koKR', 'Wróć, gdy jeszcze lepiej udowodnisz Gelkis swoją wartość!', 0),
(1371, 'koKR', 'Jeśli nie jesteś naszym wrogiem, zrobisz to, o co proszę!', 0),
(1373, 'koKR', 'Pokaż mi, że jesteś $gprzyjacielem:przyjaciółką; Gelkis, $N.', 0),
(1374, 'koKR', 'Pokaż mi, że jesteś $gprzyjacielem:przyjaciółką; Gelkis, $N.', 0),
(1375, 'koKR', 'Wykonuj zadania dla Magram, a ja ci pomogę.', 0),
(1380, 'koKR', 'Czy chan Hratha nie żyje? Masz fragment klucza?', 0),
(1381, 'koKR', 'Zrób to, o co proszę. Udowodnij mi, że jesteś $gsojusznikiem:sojuszniczką; Magram!', 0),
(1382, 'koKR', 'Precz! Gelkis nie chcą cię tutaj. Odejdź natychmiast!!$B$BWróć, gdy zabijesz wielu Magram, wtedy z tobą porozmawiam.', 0),
(1384, 'koKR', 'Masz talizmany? $GPokazałeś:Pokazałaś; Kolkarom, że są słabi?', 0),
(1385, 'koKR', 'Odejdziesz teraz albo Magram cię zmiażdżą! Żeby być naszym przyjacielem, musisz zabijać Gelkis.', 0),
(1386, 'koKR', 'Boisz się Kolkarów? Czemu ich nie zabijasz? Może nie pamiętasz już, jak się zabija. Śpiesz się i zabijaj Kolkarów, zanim sami pomrą!', 0),
(1387, 'koKR', 'Masz jakiś raport, $N?', 0),
(1439, 'koKR', 'Obawiam się, że Tyranis spróbuje poznać sekrety Płonącego Ostrza i dołączy do nich, jeśli mu na to pozwolą – zawsze uwielbiał potęgę, jaką magia daje tym, których uwiedzie.$B$BNie wiem, czy zniosłabym powrót do domu, do rodziny, z wieścią, że duch Tyranisa igra z takim niebezpieczeństwem. Już samo zgłębianie takich rzeczy jest wśród mojego ludu straszną zbrodnią, ale stać się tym, przed czym próbujemy się chronić... cóż, to karygodne.', 0),
(1456, 'koKR', 'Bez obrazy dla tego całego Nijela, ale ten obóz to nie najwygodniejsze miejsce, w jakim przyszło mi nocować, jeśli wiesz, co mam na myśli, $N.', 0),
(1458, 'koKR', 'Paskudne stwory, te satyry. Podobno są jakoś związane z nocnymi elfami, ale nie jestem pewien, czy w to wierzę.$B$BMyślę, że wzięło się to stąd, że jeden elf wciągnął je w wojnę parę lat temu. Od tamtej pory świat już nie jest taki sam. Dużo bardziej niebezpieczny i dużo straszniejszy.', 0),
(1459, 'koKR', 'Przepraszam, że nie mogłem ci powiedzieć, gdzie szukać kodo ani skorpaszy. Nie znam za dobrze okolicy i nie miałem czasu jej zbadać.', 0),
(1466, 'koKR', 'Nawet nie wiedziałem, że te demony są w Mrocznym Pustkowiu. Ostatnio czytałem, że ta ziemia właściwie należy do centaurów, odkąd nocne elfy lata temu spakowały się i odeszły.$B$BCiekawe, dlaczego tu osiadły i jak.', 0),
(1480, 'koKR', 'Płonące Ostrze zaczyna sobie uświadamiać, jak naprawdę jest słabe. Ich magia jest żałosna, a siła nikła.$B$BCałą swoją moc zawdzięczają tym, którym służą, a nie zrozumieniu prawdziwej potęgi i wiedzy.', 0),
(1481, 'koKR', 'Nie przynoś mi niewłaściwego skalpu, $N. Użycie niewłaściwych składników mogłoby skończyć się naszą śmiercią. Demoniczny lord może mieć na sobie zaklęcia, które na taką okoliczność zabiją każdego, kto spróbuje go podejrzeć wieszczeniem.$B$BLos zadał mi już dość bólu.', 0),
(1482, 'koKR', 'Jestem gotów na kryształ wyroczni, $N. Odnalezienie i zniszczenie tego lorda Azrethoca zjednałoby nam obojgu wielką przychylność wodza. Dobrze zrobimy, jeśli będziemy działać razem, i to szybko – każde z nas osiągnie własne cele i wkupi się w łaski wodza.', 0),
(1488, 'koKR', 'Chwała Hordzie i śmierć naszym wrogom, $N!$B$BDemony w Mrocznym Pustkowiu są groźniejsze niż kiedykolwiek. Moja nadzieja na powrót do wodza gaśnie, bo tych plugawych stworów zdaje się wciąż przybywać.$B$BCzasem żałuję, że nie mamy do czynienia z samymi centaurami.', 0),
(5381, 'koKR', '$n, masz demoniczną skrzynkę?', 0),
(5386, 'koKR', 'Mrowi mnie w kopycie, a do pyska napływa ślinka, gdy pomyślę o smażonej rybie krwawobrzuchej... Masz jakąś przy sobie?', 0),
(5421, 'koKR', 'Nagrodzę każdego, kto choć trochę ułatwi mi życie... Lubię robić jak najmniej, mon!$B$BPod pomostami tu, w Wiosce Cienistej Ofiary, mam mnóstwo pułapek na skorupiaki. Jeśli będziesz $gtaki miły:taka miła;, żeby odwalić za mnie robotę i zebrać moje skorupiaki, to dam ci coś, czego chcesz... łapiesz, mon? Za każde pięć skorupiaków, które mi przyniesiesz, dam ci piękną rybę krwawobrzucha!', 0),
(5501, 'koKR', 'Masz kości? Karawana będzie tu lada chwila. Brakuje mi tylko dziesięciu kości kodo do szczytu kariery. Do szczytu kariery, mówię ci!', 0),
(5561, 'koKR', 'Karawana niedługo tu będzie; masz tych pięć nowych oswojonych kodo, o które prosiłem?', 0),
(5581, 'koKR', '$GWygnałeś:Wygnałaś; demoniczne portale w Sabacie Mannoroca?', 0),
(5741, 'koKR', 'Masz Berło Światła?', 0),
(5763, 'koKR', 'Siadaj, $N. Już niedługo znów ruszysz w dżunglę.', 0),
(5821, 'koKR', 'Czemu ja właściwie czekam na tę przeklętą karawanę?$b$b<Smeeda nagle olśniewa.>$b$bA, no tak, to oni płacą rachunki. $GWidziałeś:Widziałaś; ich?', 0),
(5943, 'koKR', 'Wiesz, gdyby ta karawana kiedyś przepadła, byłbym zrujnowany! Nie przynosisz chyba złych wieści o karawanie, co?$b$b<Smeed ociera czoło.>$b$bDzięki niech będą bogini chciwości!', 0),
(6027, 'koKR', 'Ach, $N! Dobrze cię znowu widzieć. Masz Księgę Pradawnych?', 0),
(6132, 'koKR', '$GWidziałeś:Widziałaś; moją siostrę Melizzę? Ciągle jest w biegu, przez co wiecznie pakuje się w kłopoty.', 0),
(6134, 'koKR', 'Gdzie moja duchoplazma, $N?', 0),
(6142, 'koKR', 'Nie mogę się doczekać, aż pójdę na ryby ze świeżym mięsem miękkoskorupowych małży. $GPrzyniosłeś:Przyniosłaś; mi te 10 kawałków, których potrzebuję?', 0),
(6143, 'koKR', 'Wciąż słyszę ich głosy wołające o pomoc, gdy nagi rozpętały nad nami chaos. Gdyby nie to chore kolano, sam bym poszedł i pomógł ci wybić te przeklęte nagi!$B$BZwykle na pewno znajdziesz je głęboko w rafach koralowych pod powierzchnią... czają się... knują...', 0),
(6568, 'koKR', 'Rzadko widuję kogoś z Hordy w tych stronach Lordaeronu. Co masz dla Myrandy?', 0),
(6601, 'koKR', 'Nie panikuj, $N!', 0),
(6602, 'koKR', 'Chyba nie muszę ci mówić, że Drakkisata nie wolno lekceważyć.$B$BNiech za mnie przemówią tysiące poległych z jego ręki.', 0),
(7028, 'koKR', 'Nie zadawaj pytań!$B$BWiesz, o co proszę.', 0),
(7029, 'koKR', 'Jeśli zdołasz uleczyć roślinę, znów zacznie rosnąć. Musimy robić, co w naszej mocy, $N...', 0),
(7041, 'koKR', 'Jeśli zdołasz uleczyć roślinę, znów zacznie rosnąć. Musimy robić, co w naszej mocy, $N...', 0),
(7044, 'koKR', 'Obudziłem się z koszmaru, który zdawał się nie mieć końca...', 0),
(7064, 'koKR', 'Wolałabym stoczyć tę bitwę własnymi siłami, ale nie mamy innego wyjścia – potrzebujemy tych, którzy są potężniejsi, a rasy Azeroth ponad wszelką wątpliwość dowiodły, że potrafią pokonać takie przeszkody, gdy działają razem. Dlatego to do ciebie zwracamy się o pomoc.$B$BMam tylko nadzieję, że to wystarczy.$B$BZaetar, brat Remulosa, sprowadził na ten świat wiele cierpień, a w końcu doprowadził do własnej śmierci. Mam tylko nadzieję, że prosząc cię o pomoc, nie sprowadziłam jeszcze więcej śmierci.', 0),
(7065, 'koKR', 'Czuję ciężar tego, że muszę prosić o pomoc śmiertelne rasy, ale nie mamy innego wyjścia. Rasy Azeroth ponad wszelką wątpliwość dowiodły, że potrafią pokonać takie przeszkody, gdy działają razem, dlatego to je proszę o pomoc.$B$BMam tylko nadzieję, że to wystarczy.$B$BZaetar, brat Remulosa, sprowadził na ten świat wiele cierpień, a w końcu doprowadził do własnej śmierci. Płynie z tego nauka dla nas wszystkich, jeśli jesteśmy dość mądrzy, by ją dostrzec.', 0),
(7067, 'koKR', 'Co postanawiasz, $N? Możesz mi pomóc? Czy postawisz stopę na świętej ziemi, by pomóc mi wykuć jedno wielkie plemię centaurów!?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(5396, 0, 'koKR', 'Przymierze ma w Mrocznym Pustkowiu wiele do stracenia, a nasza pozycja jest tu niepewna.$B$BPomożesz nam?', 0),
(5412, 0, 'koKR', 'Klany centaurów władają jałowymi ziemiami Mrocznego Pustkowia. Zjednoczone byłyby straszliwą siłą. Dobrze więc, że klany centaurów nie są zjednoczone, tylko kłócą się i walczą między sobą.', 0),
(10321, 0, 'koKR', '<Emberstrife dostrzega twoją obecność.>', 0),
(11596, 0, 'koKR', 'Mój biznesplan nie przewidywał trzymania olbrzymich kodo... może zamiast tego trzeba było zająć się podwodnym wyplataniem koszyków.', 0);
